"""Load / cache Transformers-native Qwen3-ASR (-hf) models."""

from __future__ import annotations

import logging
import threading
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .qwen3_hf_convert import (
    convert_dir_to_hf_layout,
    looks_like_hf_layout,
    looks_like_legacy_qwen_layout,
    needs_hf_sidecar_repair,
)
from .qwen3_hf_lora import attach_lora, looks_like_lora_adapter, resolve_lora_base_dir

_log = logging.getLogger("transub_engine.asr.qwen3_hf_model")

_MODEL_CACHE: dict[str, "Qwen3HfBundle"] = {}
_MODEL_LOCK = threading.Lock()


@dataclass
class Qwen3HfBundle:
    """Processor + ASR model (+ optional ForcedAligner / LoRA)."""

    processor: Any
    model: Any
    device: str
    dtype: Any
    aligner_processor: Any | None = None
    aligner_model: Any | None = None
    is_lora: bool = False
    prefer_beam_search: bool = False

    @property
    def has_aligner(self) -> bool:
        return self.aligner_model is not None and self.aligner_processor is not None


def clear_hf_model_cache() -> int:
    with _MODEL_LOCK:
        n = len(_MODEL_CACHE)
        _MODEL_CACHE.clear()
    return n


def _enable_cuda_fast_matmul() -> None:
    try:
        import torch

        if torch.cuda.is_available():
            torch.backends.cuda.matmul.allow_tf32 = True
            torch.backends.cudnn.allow_tf32 = True
    except Exception:
        pass


def device_map_for(device: str, *, torch_mod: Any | None = None) -> str:
    torch = torch_mod
    if torch is None:
        import torch as torch  # type: ignore
    raw = str(device or "auto").strip().lower()
    if raw in ("", "auto"):
        return "cuda:0" if torch.cuda.is_available() else "cpu"
    if raw in ("cuda", "gpu"):
        return "cuda:0" if torch.cuda.is_available() else "cpu"
    if raw.startswith("cuda"):
        return raw if torch.cuda.is_available() else "cpu"
    return "cpu"


def _pick_dtype(torch: Any, device_map: str) -> Any:
    if not str(device_map).startswith("cuda"):
        return torch.float32
    # Ampere+ (sm>=8): bf16; older GPUs: fp16 (Turing lacks bf16 tensor cores).
    try:
        major, _minor = torch.cuda.get_device_capability(0)
        if int(major) >= 8:
            return torch.bfloat16
        return torch.float16
    except Exception:
        return torch.bfloat16


def _try_repair_hf_sidecars(path: Path) -> None:
    """Best-effort: copy official *-hf chat/tokenizer sidecars; keep weights."""
    if looks_like_hf_layout(path) or not needs_hf_sidecar_repair(path):
        return
    try:
        conv = convert_dir_to_hf_layout(path, force=True)
        if conv.get("ok") and conv.get("converted"):
            _log.info("Repaired Qwen3 *-hf sidecars under %s", path)
        elif not conv.get("ok"):
            _log.warning(
                "Qwen3 sidecar repair skipped/failed (%s); generate will use legacy chat path",
                conv.get("detail"),
            )
    except Exception as err:
        _log.warning("Qwen3 sidecar repair error: %s", err)


def load_qwen3_hf_bundle(
    asr_dir: Path | str,
    *,
    device: str = "auto",
    aligner_dir: Path | str | None = None,
    torch_mod: Any | None = None,
) -> Qwen3HfBundle:
    """Load AutoProcessor + AutoModelForMultimodalLM (+ optional aligner / LoRA)."""
    import torch
    from transformers import (
        AutoModelForMultimodalLM,
        AutoModelForTokenClassification,
        AutoProcessor,
    )

    torch = torch_mod or torch
    asr_path = Path(asr_dir)
    align_path = Path(aligner_dir) if aligner_dir else None
    is_lora = looks_like_lora_adapter(asr_path)
    base_path = resolve_lora_base_dir(asr_path) if is_lora else asr_path

    if not is_lora:
        _try_repair_hf_sidecars(asr_path)
    else:
        _try_repair_hf_sidecars(base_path)
    if align_path is not None and align_path.is_dir():
        _try_repair_hf_sidecars(align_path)

    if is_lora:
        if not looks_like_hf_layout(base_path) and not (base_path / "config.json").is_file():
            raise RuntimeError(
                f"Qwen3 LoRA base at {base_path} is not Transformers-native (-hf). "
                "Re-download qwen3-asr-1.7b."
            )
    elif not looks_like_hf_layout(asr_path) and not looks_like_legacy_qwen_layout(asr_path):
        raise RuntimeError(
            f"Qwen3-ASR model at {asr_path} is not Transformers-native (-hf): "
            "missing tokenizer.json / config. Delete the folder and download again."
        )
    elif not (asr_path / "config.json").is_file():
        raise RuntimeError(
            f"Qwen3-ASR model at {asr_path} is not Transformers-native (-hf): "
            "missing config.json. Delete the folder and download again."
        )

    device_map = device_map_for(device, torch_mod=torch)
    dtype = _pick_dtype(torch, device_map)
    key = f"{asr_path}|{base_path}|{align_path or ''}|{device_map}|{dtype}|lora={is_lora}"

    with _MODEL_LOCK:
        cached = _MODEL_CACHE.get(key)
        if cached is not None:
            return cached
        if str(device_map).startswith("cuda"):
            _enable_cuda_fast_matmul()

        # Processor: prefer adapter dir (ships tokenizer/processor), else base.
        proc_root = asr_path if (asr_path / "tokenizer.json").is_file() else base_path
        _log.info(
            "Loading Qwen3-ASR -hf from %s%s (device_map=%s)",
            base_path,
            f" + LoRA {asr_path.name}" if is_lora else "",
            device_map,
        )
        processor = AutoProcessor.from_pretrained(str(proc_root))
        model = AutoModelForMultimodalLM.from_pretrained(
            str(base_path),
            dtype=dtype,
            device_map=device_map,
        )
        if is_lora:
            model = attach_lora(model, asr_path)
        model.eval()

        aligner_processor = None
        aligner_model = None
        if align_path is not None and align_path.is_dir():
            _log.info("Loading Qwen3 ForcedAligner -hf from %s", align_path)
            aligner_processor = AutoProcessor.from_pretrained(str(align_path))
            aligner_model = AutoModelForTokenClassification.from_pretrained(
                str(align_path),
                dtype=dtype,
                device_map=device_map,
            )
            aligner_model.eval()

        bundle = Qwen3HfBundle(
            processor=processor,
            model=model,
            device=str(device_map),
            dtype=dtype,
            aligner_processor=aligner_processor,
            aligner_model=aligner_model,
            is_lora=is_lora,
            prefer_beam_search=is_lora,
        )
        _MODEL_CACHE[key] = bundle
        return bundle
